<script setup>
import { computed,onMounted,reactive,ref } from 'vue'
import { internalApi } from '../../internalEvaluationApi'
const tasks=ref([]),versions=ref([]),orgs=ref([]),users=ref([]),selected=ref(null),message=ref('')
const showCreate=ref(false)
const form=reactive({taskCode:'',taskName:'',evaluationYear:new Date().getFullYear(),taskType:'ANNUAL',startDate:'',endDate:'',description:'',indicatorVersionId:'',orgUnitIds:[],evaluatorId:'',reviewerId:''})
const active=computed(()=>tasks.value.filter(x=>!['COMPLETED','CANCELLED'].includes(x.status)).length)
async function load(){try{[tasks.value,versions.value,orgs.value,users.value]=await Promise.all([internalApi.tasks(),internalApi.versions(),internalApi.organizations(),internalApi.users()])}catch(e){message.value=e.message}}
async function create(){try{await internalApi.createTask({...form,indicatorVersionId:Number(form.indicatorVersionId),orgUnitIds:form.orgUnitIds.map(Number),evaluatorId:Number(form.evaluatorId),reviewerId:Number(form.reviewerId)});showCreate.value=false;message.value='任务草稿已创建';await load()}catch(e){message.value=e.message}}
async function detail(row){try{selected.value=await internalApi.task(row.id)}catch(e){message.value=e.message}}
async function publish(row){if(!confirm('发布后机构、指标版本和评分结构将冻结，是否继续？'))return;try{await internalApi.publish(row.id);await load();await detail(row)}catch(e){message.value=e.message}}
async function copy(row){const code=prompt('新任务编码',`${row.task_code}-COPY`);if(!code)return;try{await internalApi.copyTask(row.id,{taskCode:code,taskName:`${row.task_name}（副本）`,evaluationYear:row.evaluation_year+1});await load()}catch(e){message.value=e.message}}
async function cancel(row){const reason=prompt('请输入取消原因');if(!reason)return;try{await internalApi.taskStatus(row.id,{status:'CANCELLED',reason,rowVersion:row.row_version});await load()}catch(e){message.value=e.message}}
onMounted(load)
</script>
<template><section class="page active">
  <div class="alert alert-info">专项、年度和机构调整后评估统一管理；发布时冻结三级指标、标准分、权重和评分规则快照。</div><div v-if="message" class="alert alert-warning">{{message}}</div>
  <div class="stat-grid"><div class="stat-card"><div class="num">{{tasks.length}}</div><div class="label">评价任务</div><div class="sub">全部版本</div></div><div class="stat-card"><div class="num green">{{active}}</div><div class="label">进行中</div><div class="sub">未完成/取消</div></div><div class="stat-card"><div class="num orange">{{tasks.reduce((n,x)=>n+Number(x.org_count||0),0)}}</div><div class="label">参评机构</div><div class="sub">任务口径</div></div><div class="stat-card"><div class="num">{{versions.length}}</div><div class="label">可选指标版本</div><div class="sub">仅已发布</div></div></div>
  <div class="card"><div class="card-header"><h3>🗂️ 评价任务分类管理</h3><button class="btn btn-primary" @click="showCreate=true">创建任务</button></div><div class="table-scroll"><table><thead><tr><th>任务编码</th><th>任务名称</th><th>类型</th><th>年度/时间</th><th>指标版本</th><th>机构</th><th>评分进度</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-if="!tasks.length"><td colspan="9" class="empty-cell">暂无评价任务</td></tr><tr v-for="row in tasks" :key="row.id"><td>{{row.task_code}}</td><td>{{row.task_name}}</td><td>{{row.task_type}}</td><td>{{row.evaluation_year}} / {{row.start_date||'-'}}～{{row.end_date||'-'}}</td><td>{{row.system_name}} / {{row.version_name}}</td><td>{{row.org_count}}</td><td>{{row.confirmed_count}} / {{row.org_count}}（{{row.progress_percent}}%）</td><td><span class="tag tag-info">{{row.status}}</span></td><td><div class="btn-group"><button class="btn btn-sm btn-outline" @click="detail(row)">详情</button><button v-if="row.status==='DRAFT'" class="btn btn-sm btn-primary" @click="publish(row)">发布</button><button class="btn btn-sm btn-outline" @click="copy(row)">复制</button><button v-if="!['COMPLETED','CANCELLED'].includes(row.status)" class="btn btn-sm btn-outline" @click="cancel(row)">取消</button></div></td></tr></tbody></table></div></div>
  <div v-if="showCreate" class="evidence-modal show" @click.self="showCreate=false"><div class="evidence-panel"><div class="panel-head"><h3>创建评价任务</h3><button class="btn btn-outline" @click="showCreate=false">关闭</button></div><div class="panel-body"><div class="search-bar"><div class="form-item"><label>任务编码</label><input v-model.trim="form.taskCode"></div><div class="form-item"><label>任务名称</label><input v-model.trim="form.taskName"></div><div class="form-item"><label>年度</label><input v-model.number="form.evaluationYear" type="number"></div><div class="form-item"><label>任务类型</label><select v-model="form.taskType"><option value="SPECIAL">专项评估</option><option value="ANNUAL">年度评估</option><option value="POST_ADJUSTMENT">机构调整后评估</option></select></div><div class="form-item"><label>开始日期</label><input v-model="form.startDate" type="date"></div><div class="form-item"><label>结束日期</label><input v-model="form.endDate" type="date"></div><div class="form-item"><label>已发布指标版本</label><select v-model="form.indicatorVersionId"><option value="">请选择</option><option v-for="v in versions" :key="v.id" :value="v.id">{{v.system_name}} / {{v.version_name}}（{{v.score_item_count}}项）</option></select></div><div class="form-item"><label>评分人员</label><select v-model="form.evaluatorId"><option value="">请选择</option><option v-for="u in users" :key="u.id" :value="u.id">{{u.display_name}}</option></select></div><div class="form-item"><label>复核人员</label><select v-model="form.reviewerId"><option value="">请选择</option><option v-for="u in users" :key="u.id" :value="u.id">{{u.display_name}}</option></select></div><div class="form-item"><label>说明</label><input v-model.trim="form.description"></div></div><h4>参评机构</h4><div class="version-list"><label v-for="org in orgs" :key="org.id" class="version-item"><span><input v-model="form.orgUnitIds" type="checkbox" :value="org.id"> {{org.unit_name}}</span></label></div><button class="btn btn-primary" @click="create">保存草稿</button></div></div></div>
  <div v-if="selected" class="evidence-modal show" @click.self="selected=null"><div class="evidence-panel"><div class="panel-head"><h3>{{selected.task_name}}</h3><button class="btn btn-outline" @click="selected=null">关闭</button></div><div class="panel-body"><div class="alert alert-info">{{selected.status}} / {{selected.system_name}} / {{selected.version_name}} / 快照{{selected.snapshots.length}}项</div><h4>参评机构与评分进度</h4><div v-for="org in selected.organizations" :key="org.id" class="version-item"><span>{{org.unit_name}} / 评分：{{org.evaluator_name}} / 复核：{{org.reviewer_name}}</span><span class="tag tag-info">{{org.score_status||'待发布'}} / {{org.total_score||0}}分</span></div><h4>任务版本与状态历史</h4><div v-for="item in selected.history" :key="item.id" class="version-item"><span>{{item.from_status||'新建'}} → {{item.to_status}} / {{item.reason||'-'}}</span><span>{{item.operator_name}} {{item.changed_at}}</span></div></div></div></div>
</section></template>
